def transform_insert_insert(op1, op2):
    # Both try to insert at the same time.
    if op1.index < op2.index:
        # Op1 happened earlier in the string. 
        # Op2 needs to be pushed to the right.
        return Insert(op2.index + len(op1.text), op2.text)
    elif op1.index > op2.index:
        # Op1 happened later. Op2 stays where it is.
        return op2
    else:
        # Exact same index. Tie-breaker via arbitrary UUID prioritization.
        if op1.client_id < op2.client_id:
            return Insert(op2.index + len(op1.text), op2.text)
        else:
            return op2

public class CollaborationServer {
    // Thread-safe map of active document sessions
    private final Map<String, DocumentSession> sessions = new ConcurrentHashMap<>();

    @OnMessage
    public void onOperation(Session client, String docId, Operation op) {
        DocumentSession doc = sessions.get(docId);
        synchronized(doc) {
            // 1. Transform op against history since client's last known version
            Operation transformed = doc.getOTEngine().transform(op);
            // 2. Apply to server copy
            doc.apply(transformed);
            // 3. Broadcast to all OTHER clients
            doc.broadcastExcept(client, transformed);
        }
    }
}

try-catch fallback mechanics:
1. SplitBrainException: Client loses internet on airplane while typing. The local buffer stores the pending operations. Upon reconnecting 5 hours later, the client must fetch the server's entire history (potentially 5,000 revisions) and run the transform logic locally against its massive buffer before it can safely send its delayed edits.
2. Server Memory Exhaustion: An OT server holds the entire document in RAM. If 1,000 users open a 500-page doc, the node OOMs. Mitigate by dynamically offloading inactive sections of the document to Redis caching.
